```cpp
#include <vector>
#include <algorithm>

void ordenarVector(std::vector<int>& datos, bool descendente = false) {
    if (descendente) {
        std::sort(datos.begin(), datos.end(), std::greater<int>());
    } else {
        std::sort(datos.begin(), datos.end());
    }
}
```

