```javascript
function busquedaBinaria(arr, objetivo) {
  let izq = 0;
  let der = arr.length - 1;
  while (izq <= der) {
    const medio = Math.floor((izq + der) / 2);
    if (arr[medio] === objetivo) return medio;
    if (arr[medio] < objetivo) {
      izq = medio + 1;
    } else {
      der = medio - 1;
    }
  }
  return -1;
}
```

