```python
def parentesis_balanceados(cadena: str) -> bool:
    pares = {")": "(", "]": "[", "}": "{"}
    aperturas = set(pares.values())
    pila = []
    for ch in cadena:
        if ch in aperturas:
            pila.append(ch)
        elif ch in pares:
            if not pila or pila.pop() != pares[ch]:
                return False
    return len(pila) == 0
