```python
class NodoTrie:
    def __init__(self):
        self.hijos: dict[str, NodoTrie] = {}
        self.es_fin: bool = False

class Trie:
    def __init__(self):
        self.raiz = NodoTrie()

    def insertar(self, palabra: str) -> None:
        nodo = self.raiz
        for ch in palabra:
            if ch not in nodo.hijos:
                nodo.hijos[ch] = NodoTrie()
            nodo = nodo.hijos[ch]
        nodo.es_fin = True

    def buscar_prefijo(self, prefijo: str) -> bool:
        nodo = self.raiz
        for ch in prefijo:
            if ch not in nodo.hijos:
                return False
            nodo = nodo.hijos[ch]
        return True
```

