Un **Ring Buffer (Buffer Circular)** de tamaño fijo en pila/BSS permite encolar y desencolar bytes en tiempo $O(1)$ sin fragmentar la RAM con `malloc`:

```cpp
#include <stdint.h>
#include <stdbool.h>

template <typename T, uint16_t CAPACIDAD>
class RingBuffer {
    T buffer_[CAPACIDAD];
    volatile uint16_t cabeza_ = 0;
    volatile uint16_t cola_ = 0;
public:
    bool push(T item) {
        uint16_t sig = (cabeza_ + 1) % CAPACIDAD;
        if (sig == cola_) return false; // Buffer lleno
        buffer_[cabeza_] = item;
        cabeza_ = sig;
        return true;
    }

    bool pop(T& destino) {
        if (cabeza_ == cola_) return false; // Buffer vacío
        destino = buffer_[cola_];
        cola_ = (cola_ + 1) % CAPACIDAD;
        return true;
    }
};
```

