El *borrow checker* de **Rust** impide condiciones de carrera en tiempo de compilación. Usa `Arc<Mutex<T>>` (*Atomically Reference Counted* + *Mutual Exclusion*) para compartir estado entre hilos:

```rust
use std::sync::{Arc, Mutex};
use std::thread;

pub fn sumar_concurrente(num_hilos: usize) -> i32 {
    let contador = Arc::new(Mutex::new(0));
    let mut manejadores = Vec::with_capacity(num_hilos);

    for _ in 0..num_hilos {
        let clon = Arc::clone(&contador);
        let h = thread::spawn(move || {
            if let Ok(mut num) = clon.lock() {
                *num += 1;
            }
        });
        manejadores.push(h);
    }

    for h in manejadores {
        let _ = h.join();
    }
    let resultado = *contador.lock().unwrap();
    resultado
}
```

