En **Go (Golang)**, un *Worker Pool* con `goroutines`, canales tipados (`chan`) y `sync.WaitGroup` procesa miles de tareas concurrentes con un consumo mínimo de RAM:

```go
package main

import (
	"sync"
)

func ProcesarConWorkerPool(trabajos []int, numWorkers int) []int {
	jobs := make(chan int, len(trabajos))
	results := make(chan int, len(trabajos))
	var wg sync.WaitGroup

	for w := 0; w < numWorkers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for n := range jobs {
				results <- n * n
			}
		}()
	}

	for _, t := range trabajos {
		jobs <- t
	}
	close(jobs)

	wg.Wait()
	close(results)

	salida := make([]int, 0, len(trabajos))
	for r := range results {
		salida = append(salida, r)
	}
	return salida
}
```

